def control(obs):
    m=obs.get('local_map') or {}
    L=m.get('left_rail',[]); R=m.get('right_rail',[])
    def interp(ps,u):
        ps=sorted(ps,key=lambda p:p[0])
        for a,b in zip(ps,ps[1:]):
            if a[0]<=u<=b[0] and b[0]!=a[0]:
                q=(u-a[0])/(b[0]-a[0]); return a[1]+q*(b[1]-a[1])
        return ps[-1][1] if ps else None
    u=2.0; l=interp(L,u); r=interp(R,u)
    c=(l+r)/2 if l is not None and r is not None else (l-1.85 if l is not None else r+1.85 if r is not None else 0)
    h=float(obs.get('hitch_deg',0))
    steer=max(-24,min(24,-c*4+h*0.65))
    return (steer,-0.4,180)

