def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    status = obs.get('status', '')
    if status in ('PINNED', 'JACKKNIFED') or abs(h) > 3.0:
        return (0.0, 0.30, 180)
    m = obs.get('local_map') or {}
    L = m.get('left_rail', [])
    R = m.get('right_rail', [])
    def at(ps, u):
        ps = sorted(ps, key=lambda p: p[0])
        for a, b in zip(ps, ps[1:]):
            if a[0] <= u <= b[0] and b[0] != a[0]:
                q = (u-a[0])/(b[0]-a[0])
                return a[1] + q*(b[1]-a[1])
        return ps[-1][1] if ps else None
    l, r = at(L, 2.0), at(R, 2.0)
    c = (l+r)/2.0 if l is not None and r is not None else 0.0
    # While reversing, steer with the hitch angle to damp sway; bias toward
    # the rail midpoint ahead of the trailer.
    steer = max(-16.0, min(16.0, 0.55*h - 2.5*c))
    return (steer, -0.22, 180)

