def control(obs):
    h=float(obs.get('hitch_deg',0.0))
    view=obs.get('view',{})
    left=view.get('left_rail',[])
    right=view.get('right_rail',[])
    def at(points,u):
        if not points:return None
        p=min(points,key=lambda q:abs(float(q[0])-u))
        return float(p[1])
    mids=[]
    for u in (0.0,1.5,3.0,4.5):
        a,b=at(left,u),at(right,u)
        if a is not None and b is not None:mids.append((u,(a+b)*0.5))
    center=mids[0][1] if mids else 0.0
    slope=(mids[-1][1]-mids[0][1])/(mids[-1][0]-mids[0][0]) if len(mids)>1 else 0.0
    steer=max(-8.0,min(8.0,0.24*h-1.0*center-9.0*slope))
    speed=-0.08 if abs(h)>22 else -0.10
    return (steer,speed,180.0)

