def control(obs):
    h=float(obs.get('hitch_deg',0.0))
    view=obs.get('view',{})
    left=view.get('left_rail',[])
    right=view.get('right_rail',[])
    def at(points,u):
        if not points:return None
        pts=sorted(points,key=lambda p:float(p[0]))
        if u<=pts[0][0]:return float(pts[0][1])
        if u>=pts[-1][0]:return float(pts[-1][1])
        for (u0,v0),(u1,v1) in zip(pts,pts[1:]):
            if u0<=u<=u1:
                f=(u-u0)/(u1-u0) if u1!=u0 else 0.0
                return float(v0)+f*(float(v1)-float(v0))
    mids=[]
    for u in (0.0,1.5,3.0):
        a,b=at(left,u),at(right,u)
        if a is not None and b is not None:mids.append((u,(a+b)*0.5))
    center=mids[0][1] if mids else 0.0
    slope=(mids[-1][1]-mids[0][1])/(mids[-1][0]-mids[0][0]) if len(mids)>1 else 0.0
    steer=max(-5.0,min(8.0,0.18*h-1.2*center-5.0*slope))
