def control(obs):
    view = obs.get("view", {})
    left = view.get("left_rail", [])
    right = view.get("right_rail", [])
    def interp(points, x):
        pts = sorted((p[0], p[1]) for p in points if len(p) >= 2)
        if len(pts) < 2:
            return None
        for i in range(len(pts)-1):
            x0,y0=pts[i]; x1,y1=pts[i+1]
            if x0 <= x <= x1 and x1 != x0:
                return y0+(y1-y0)*(x-x0)/(x1-x0)
        return min(pts, key=lambda p: abs(p[0]-x))[1]
    targets=[]
    for x in (1.2, 2.0, 2.8):
        a=interp(left,x); b=interp(right,x)
        if a is not None and b is not None:
            targets.append((x,(a+b)*0.5))
    path_cmd=0.0
    if targets:
        x,v=targets[-1]
        path_cmd=max(-20.0,min(20.0,-v*10.0))
    h=obs.get("hitch_deg",0.0)
    steer=max(-35.0,min(35.0,path_cmd+0.9*h))
    return (steer,-0.55,180.0)

