def control(obs):
    view=obs.get('view',{})
    L=sorted((p[0],p[1]) for p in view.get('left_rail',[]) if len(p)>=2)
    R=sorted((p[0],p[1]) for p in view.get('right_rail',[]) if len(p)>=2)
    def at(pts,x):
        if not pts: return None
        for i in range(len(pts)-1):
            x0,y0=pts[i]; x1,y1=pts[i+1]
            if x0<=x<=x1 and x1!=x0: return y0+(y1-y0)*(x-x0)/(x1-x0)
        return min(pts,key=lambda p:abs(p[0]-x))[1]
    vals=[]
    for x in (0.5,1.5,2.5,3.5):
        a=at(L,x); b=at(R,x)
        if a is not None and b is not None: vals.append((x,(a+b)/2))
    if len(vals)>=2:
        x,y=vals[-1]
        path=max(-18,min(18,-6.0*y + 7.0*(vals[-1][1]-vals[0][1])))
    elif L:
        y=at(L,1.0)
        path=max(-12,min(12,(y-1.65)*8)) if y is not None else 0
    elif R:
        y=at(R,1.0)
        path=max(-12,min(12,(y+1.65)*8)) if y is not None else 0
    else: path=0
    h=obs.get('hitch_deg',0.0)
    steer=max(-24,min(24,path+0.8*h))
    return (steer,-0.20,180.0)

