import math
def control(obs):
    view=obs.get('view',{})
    left=view.get('left_rail',[])
    right=view.get('right_rail',[])
    pairs=[]
    for p in left:
        if right:
            q=min(right,key=lambda z:abs(z[0]-p[0]))
            if abs(q[0]-p[0])<2.2:
                pairs.append((p[0],(p[1]+q[1])*0.5))
    pairs.sort()
    # Aim at the course center a few metres ahead; reverse steering moves the trailer rear opposite the wheel direction.
    target=min((p for p in pairs if 4<=p[0]<=10),key=lambda p:abs(p[0]-7),default=None)
    steer=0.0
    if target is not None:
        steer=max(-10.0,min(10.0,-math.degrees(math.atan2(target[1],max(3.0,target[0])))*1.2))
    h=obs.get('hitch_deg',0.0)
    steer=max(-14.0,min(14.0,steer-0.7*h))
    return (steer,-0.30,180.0)

